/** The generated src/lib/combat-map/area-effects/manifest.ts (pnpm sprites:areas). */

import { AREA_KINDS } from "../../../src/lib/combat-map/area-effects/kinds";
import type { AreaManifest } from "../../../src/lib/combat-map/area-effects/manifest-schema";

export function areaManifestSource(manifest: AreaManifest): string {
  const lines = [
    "/**",
    " * GENERATED by `pnpm sprites:areas` (scripts/sprite-packs/cut-areas.ts). Do not edit by hand: rerun the cutter on the",
    " * area-effect sheets (docs/sprite-packs/area-effects-prompts.md). Files live under public/area-effects/ and are",
    " * content-hashed, so they are served immutable.",
    " */",
    "",
    'import type { AreaManifest } from "./manifest-schema";',
    "",
    "export const AREA_MANIFEST: AreaManifest = {",
    `  schemaVersion: ${manifest.schemaVersion},`,
    "  kinds: {",
  ];
  // AREA_KINDS order, fixed key order: a rerun on the same sheets writes identical lines.
  for (const kind of AREA_KINDS) {
    const e = manifest.kinds[kind];
    if (e) lines.push(`    ${JSON.stringify(kind)}: ${JSON.stringify({ file: e.file, px: { w: e.px.w, h: e.px.h } })},`);
  }
  lines.push("  },", "};", "");
  return lines.join("\n");
}
